+    const saved = withBrokeredNativeDeliveryInvocation({
+      root,
+      store,
+      storyId,
+      invoke: () => handlers.delivery_check_set({
+        storyId,
+        agentId: 'lattice-review-delivery',
+        docsPromises: [],
+        realMachineTests: [],
+        closingSelfCheck: {
+          hasRealMachineTest: false,
+          hasEdgeCaseCoverage: true,
+          hasUnresolvedTodos: false,
+          summary: 'Brokered delivery reviewer authors exact formal evidence.',
+        },
+      }),
+    });
+    assert.match(saved, /Delivery check saved/);
+    assert.equal(store.readDeliveryCheck(storyId)?.agentId, 'lattice-review-delivery');
+  } finally {
+    resetSessionIdForTest();
+    if (previous.agent === undefined) delete process.env.LATTICE_AGENT; else process.env.LATTICE_AGENT = previous.agent;
+    if (previous.sessionId === undefined) delete process.env.LATTICE_SESSION_ID; else process.env.LATTICE_SESSION_ID = previous.sessionId;
+    if (previous.provider === undefined) delete process.env.LATTICE_OWNER_SESSION_ADAPTER_PROVIDER; else process.env.LATTICE_OWNER_SESSION_ADAPTER_PROVIDER = previous.provider;
+    if (previous.task === undefined) delete process.env.LATTICE_OWNER_SESSION_ADAPTER_TASK; else process.env.LATTICE_OWNER_SESSION_ADAPTER_TASK = previous.task;
+    if (previous.adapterAgent === undefined) delete process.env.LATTICE_OWNER_SESSION_ADAPTER_AGENT; else process.env.LATTICE_OWNER_SESSION_ADAPTER_AGENT = previous.adapterAgent;
+  }
+
+  console.log('delivery-check-native-attestation smoke: PASS');
+} finally {
+  rmSync(root, { recursive: true, force: true });
+}
