+  writeFileSync(path, `${JSON.stringify(invocation.attestation)}\n`, { mode: 0o600 });
+  const fd = openSync(path, 'r');
+  const envKeys = [
+    'LATTICE_NATIVE_REVIEW_ATTESTATION_FD',
+    'LATTICE_SESSION_ID',
+    'LATTICE_AGENT',
+    'LATTICE_OWNER_SESSION_ADAPTER_PROVIDER',
+    'LATTICE_OWNER_SESSION_ADAPTER_TASK',
+    'LATTICE_OWNER_SESSION_ADAPTER_AGENT',
+    'CLAUDE_CODE_SESSION_ID',
+  ] as const;
+  const previous = Object.fromEntries(envKeys.map(key => [key, process.env[key]]));
+  try {
+    process.env.LATTICE_NATIVE_REVIEW_ATTESTATION_FD = String(fd);
+    Object.assign(process.env, invocation.env);
+    resetSessionIdForTest();
+    return args.invoke();
+  } finally {
+    resetSessionIdForTest();
+    for (const key of envKeys) {
+      const value = previous[key];
+      if (value === undefined) delete process.env[key];
+      else process.env[key] = value;
+    }
+    closeSync(fd);
+    unlinkSync(path);
+  }
+}
